class StartAgentSessionRequest(EllipsisModel):
    """Start a session from a saved agent. The body takes the fields of POST
    /v1/sessions, all optional, plus `input`, and is merged into the agent's
    `session` settings. An object merges key by key, any other value replaces
    the agent's, a field you leave out keeps the agent's, and `null` removes
    the agent's value so its default applies. An `environment` object is
    merged into the agent's environment, a saved one included, and an
    environment name replaces it. `output.json_schema` is replaced whole, and
    naming the other harness replaces the agent's harness. `input` is required when the agent declares
    `input.json_schema` and rejected when it doesn't. Extra keys are a 422.
    """

    budget: Union[RunBudget, None] = Field(
        default=None,
        description="Spend limit for this session. `session` is the most it may spend, in US dollars. Omitted, an agent session keeps the agent's limit and a raw session takes the organization's default. `null` takes the organization's default. Above the organization's per-session ceiling is a 400. `day`, `week`, and `month` are agent-wide limits and are rejected with a 422.",
    )
    claude_code: Union[ClaudeCodeOverrides, None] = Field(
        default=None,
        description="Claude Code options merged into the agent's for this session. Naming Claude Code on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    codex: Union[CodexOverrides, None] = Field(
        default=None,
        description="Codex options merged into the agent's for this session. Naming Codex on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    conversation: Union[SessionConversationConfigPatch, None] = Field(
        default=None,
        description="Conversation settings merged into the agent's for this session. Omitted, the session keeps the agent's setting. `null` makes it interactive.",
    )
    environment: Union[str, EnvironmentConfig, None] = Field(
        default=None,
        description="Where the session runs. A STRING is a saved environment's name or `env_...` id and replaces the agent's environment. An OBJECT is merged into the agent's environment, a saved one included: an object inside it merges key by key, any other value replaces the agent's, and `null` removes a value so its default applies. Omitted, the session keeps the agent's environment. `null` runs it in the built-in basic environment.",
    )
    force_rebuild: Union[bool, None] = Field(
        default=None,
        description="Skip the image cache for this session's initial provision: a fresh full build whose snapshot then refreshes the cache for later sessions. The CLI's `--rebuild`.",
    )
    gemini: Union[GeminiOverrides, None] = Field(
        default=None,
        description="Gemini CLI options merged into the agent's for this session. Naming Gemini CLI on an agent that runs another harness replaces its harness and requires a model. Set at most one of claude_code, codex, or gemini.",
    )
    idempotency_key: Union[str, None] = Field(
        default=None,
        description="Optional retry safety key, unique per account across POST /v1/sessions and POST /v1/agents/{id}/sessions. A retry with the same key returns the session the first request started instead of starting another. Only a request that started a session holds its key. A key is kept for 90 days. The SDKs make a key for each call that sets none, so their own retries never start a second session.",
    )
    images: Union[list[ImageAttachment], None] = Field(
        default=None,
        description="Images attached to the first message, base64 inline. Requires the model's `images` capability, listed by `/v1/account/models`. Each becomes an `[Image #N]` placeholder in the prompt and an image block the model sees with it. Up to 10, 5 MiB each; PNG, JPEG, GIF, or WebP.",
    )
    input: Union[dict[str, Any], None] = Field(
        default=None,
        description="The typed payload for an agent that declares input.json_schema. Required when the agent declares a schema; rejected when it does not. Validated against the schema. Each {{field}} in the session's prompt, the agent's or one this request sends, is replaced with that field's value. A prompt that names no field gets the payload as formatted JSON after it.",
    )
    mcp: Union[
        list[Union[str, McpServerRef, McpRemoteServer, McpCommandServer]], None
    ] = Field(
        default=None,
        description="MCP servers for this session, added to the servers its environment lists. A server with the same name as one of the environment's replaces it.",
    )
    metadata: Union[ConfigMetadataPatch, None] = Field(
        default=None,
        description="Metadata merged into the agent's for this session. Labels you send replace the agent's. Each annotation key you send sets that key, a `null` value removes the agent's key, and keys you leave out keep the agent's values. `null` removes all of the agent's metadata.",
    )
    output: Union[OutputConfigPatch, None] = Field(
        default=None,
        description="The structured-output exit contract merged into the agent's for this session. `null` removes the agent's.",
    )
    permissions: Union[PermissionsConfig, None] = Field(
        default=None, description="What the session may touch, per minted credential."
    )
    skills: Union[list[SkillRef], None] = Field(
        default=None, description="Skills installed for this session."
    )


