    idempotency_key: Union[str, None] = Field(
        default=None,
        description="Optional retry safety key, unique per account across POST /v1/sessions and POST /v1/agents/{id}/sessions. A retry with the same key returns the session the first request started instead of starting another. Only a request that started a session holds its key. A key is kept for 90 days. The SDKs make a key for each call that sets none, so their own retries never start a second session.",
    )
    images: Union[list[ImageAttachment], None] = Field(
        default=None,
        description="Images attached to the first message, base64 inline. Requires the model's `images` capability, listed by `/v1/account/models`. Each becomes an `[Image #N]` placeholder in the prompt and an image block the model sees with it. Up to 10, 5 MiB each; PNG, JPEG, GIF, or WebP.",
    )
    mcp: Union[
        list[Union[str, McpServerRef, McpRemoteServer, McpCommandServer]], None
    ] = Field(
        default=None,
        description="MCP servers for this session, added to the servers its environment lists. A server with the same name as one of the environment's replaces it.",
    )
    metadata: Union[ConfigMetadata, None] = Field(
        default=None,
        description="Labels and annotations stored on the session, to filter sessions by.",
    )
    output: Union[OutputConfig, None] = Field(
        default=None,
        description="The structured-output exit contract for this session.",
    )
    permissions: Union[PermissionsConfig, None] = Field(
        default=None, description="What the session may touch, per minted credential."
    )
    skills: Union[list[SkillRef], None] = Field(
        default=None, description="Skills installed for this session."
    )


